/**
 * Workspace data model — the single source of truth for the workspace system.
 *
 * Glossary — three levels, deliberately kept apart (one word per concept):
 *
 *   VIEW     — WHAT is open (an editor, a calculator). Never a property of
 *              placement; a "tab" is just a view placed in a stack.
 *   STACK    — a group of views rendered as tabs. Knows nothing about WHERE
 *              it is displayed; one stack type serves every surface.
 *   SURFACE  — WHERE a stack is displayed: a leaf of the tiled tree, a
 *              floating window, or a popout browser window. Moving a view
 *              changes surfaces/state only — never the view.
 *
 * This module is intentionally React-free and DOM-free so it can be unit
 * tested and reused outside the UI layer.
 */

/** Identifies a kind of view, resolved against the consumer's views map. */
export type ViewType = string;

/** A single open thing. `id` is stable for the lifetime of the view. */
export interface WorkspaceView {
 id: string;
 type: ViewType;
 title: string;
 /** Whether workspace controls may close this view. Defaults to true. */
 closable?: boolean;
 /** Keep this view on its current kind of surface. Defaults to false. */
 pinned?: boolean;
}

/**
 * A group of views rendered as tabs. Exactly one view is active at a time.
 * An empty stack (no views) is valid and renders an empty state.
 */
export interface TabStack {
 id: string;
 viewIds: string[];
 activeViewId: string | null;
}

/**
 * The tiled layout tree. The tree references stacks by id — it never embeds
 * views. Splits hold normalized ratios (0 < ratio < 1) so they scale with
 * their container.
 */
export type LayoutNode = LayoutStack | LayoutSplit;

export interface LayoutStack {
 type: "stack";
 stackId: string;
}

export interface LayoutSplit {
 type: "split";
 /** Stable id so resize handles (and drop targets) can address it. */
 id: string;
 /** "horizontal" = side by side, "vertical" = stacked top/bottom. */
 direction: "horizontal" | "vertical";
 /** Fraction of the container given to `first` (0..1). */
 ratio: number;
 first: LayoutNode;
 second: LayoutNode;
}

/**
 * A floating surface hosting one stack, positioned over the tiled area.
 * Geometry lives in state (not component state) so it persists and can be
 * serialized.
 */
export interface FloatingSurface {
 id: string;
 /** The stack this window hosts (a stack lives in the tree OR in a float). */
 stackId: string;
 x: number;
 y: number;
 width: number;
 height: number;
 /** Stacking order; higher is in front. Mirrors into DOM z-index. */
 zIndex: number;
}

/**
 * A popout surface: a stack hosted in its own browser window
 * (`window.open`). Only serializable facts live here; the live `Window`
 * handle is managed by the popouts hook layer, keyed by surface id.
 */
export interface PopoutSurface {
 id: string;
 /** The stack this window hosts (single-view stack per popout). */
 stackId: string;
 /** Initial window dimensions; the user may resize the OS window freely. */
 width: number;
 height: number;
}

/** The entire workspace state. Pure data — serializable for persistence. */
export interface WorkspaceState {
 views: Record<string, WorkspaceView>;
 stacks: Record<string, TabStack>;
 /** The main tiled surface's split tree. */
 tiled: LayoutNode;
 /**
  * The stack the user is currently working in (last clicked tab strip).
  * New views open here and "split" targets it when no explicit stack is
  * given. Null when no stack has been focused yet.
  */
 activeStackId: string | null;
 /** Floating surfaces over the tiled area. */
 floating: Record<string, FloatingSurface>;
 /** Popout surfaces in their own browser windows. */
 popouts: Record<string, PopoutSurface>;
 /** Monotonic counter for assigning z-order to floating surfaces. */
 nextZIndex: number;
}

/**
 * Tiny id helper for workspace entities. Prefixes keep ids readable when
 * debugging state ("view-x", "stack-x", ...).
 */

let counter = 0;

export function createId(prefix: string): string {
 counter += 1;
 const random = Math.random().toString(36).slice(2, 8);
 return `${prefix}-${counter.toString(36)}${random}`;
}

/**
 * All state transitions are expressed as plain action objects handled by the
 * reducer. Keeping them serializable makes time-travel debugging, undo, and
 * persistence straightforward later.
 */

import type { ViewType } from "./types";

export type WorkspaceAction =
 /**
  * Open a new view of `viewType` and add it to a stack. If `stackId` is
  * omitted, the active stack is used (falling back to the first stack in
  * the tiled tree). The new view becomes active in its stack.
  */
 | { type: "view/open"; viewType: ViewType; title?: string; closable?: boolean; pinned?: boolean; stackId?: string }

 /** Close a view. Empty stacks are pruned from the tree automatically. */
 | { type: "view/close"; viewId: string }

 /** Make a view the active tab of the stack that contains it. */
 | { type: "view/activate"; viewId: string }

 /**
  * Split the tree at the node holding `stackId` (defaults to the active
  * stack), creating a new stack as the second child. The new stack receives
  * either a newly opened view (`viewType`) or an existing view moved out of
  * the split stack (`viewId`). The new stack becomes the active stack.
  */
 | {
    type: "stack/split";
    stackId?: string;
    direction: "horizontal" | "vertical";
    ratio?: number;
    viewType?: ViewType;
    title?: string;
    closable?: boolean;
    pinned?: boolean;
    viewId?: string;
   }

 /**
  * Set the ratio of the split with `splitId`. Clamped by the reducer so a
  * pane can never be squeezed out of existence.
  */
 | { type: "layout/resize"; splitId: string; ratio: number }

 /**
  * Float a view in a new floating window. With `viewId`, an existing view
  * moves out of its tiled stack (which is pruned if it becomes empty);
  * with `viewType`, a new view opens straight into the float. Geometry
  * defaults cascade from the top-left; pass `geometry` to place explicitly.
  */
 | {
    type: "view/float";
    viewId?: string;
    viewType?: ViewType;
    title?: string;
    closable?: boolean;
    pinned?: boolean;
    geometry?: { x: number; y: number; width: number; height: number };
   }

 /** Move a view out of a floating window back into the tiled tree. */
 | { type: "view/dock"; viewId: string }

 /**
  * Move a view into another stack. "center" adds it as a tab; edges split
  * the target stack in the tiled tree and place the view in the new half
  * (50/50). Edge drops targeting a floating window are treated as "center"
  * — windows host a single stack and don't split (yet).
  */
 | {
    type: "view/move";
    viewId: string;
    targetStackId: string;
    edge: "top" | "right" | "bottom" | "left" | "center";
   }

 /** Move a view into a popout browser window (single-view stack). */
 | {
    type: "view/popout";
    surfaceId: string;
    viewId: string;
    width?: number;
    height?: number;
   }

 /** Close a popout window and all views inside it. */
 | { type: "popout/close"; surfaceId: string }

 /** Reposition a floating window. Coordinates are unclamped. */
 | { type: "floating/move"; surfaceId: string; x: number; y: number }

 /** Resize a floating window. Clamped to minimum dimensions. */
 | { type: "floating/resize"; surfaceId: string; width: number; height: number }

 /** Bring a floating window to the front and focus its stack. */
 | { type: "floating/focus"; surfaceId: string }

 /** Close a floating window and all views inside it. */
 | { type: "floating/close"; surfaceId: string };

/**
 * Pure reducer for workspace state — a thin command interpreter over the
 * model layer:
 *
 *   model/stack.ts   — tab-level ops on a single stack record
 *   model/layout.ts  — tiled tree surgery (split, prune, resize)
 *   model/surface.ts — floating surfaces + unified view placement lookup
 *
 * Every operation is a plain function from (state, action) => state over
 * serializable data; the UI layer is only a projection of this.
 */

import type { WorkspaceAction } from "./actions";
import { createId } from "./ids";
import type { WorkspaceCommand } from "./keymap";
import type { DropEdge } from "./drop-edge";
import { withoutKey } from "./model/record";
import {
  activateView as activateTab,
  addView,
  createStack,
  createView,
  cycleActive,
  holdsView,
  removeView,
} from "./model/stack";
import {
  findFirstStackId,
  splitBeside,
  splitAtEdge,
  pruneStack,
  resizeSplit,
} from "./model/layout";
import {
  DEFAULT_POPOUT_HEIGHT,
  DEFAULT_POPOUT_WIDTH,
  cascadeGeometry,
  clampSurfaceSize,
  findPopoutForView,
  findStackIdForView,
  findSurfaceForStack,
  findSurfaceForView,
  isSurfaceStack,
} from "./model/surface";
import type {
  FloatingSurface,
  LayoutNode,
  LayoutStack,
  PopoutSurface,
  TabStack,
  WorkspaceState,
} from "./types";

export function reducer(
  state: WorkspaceState,
  action: WorkspaceAction,
): WorkspaceState {
  switch (action.type) {
    case "view/open":
      return openView(state, action);
    case "view/close":
      return closeView(state, action.viewId);
    case "view/activate":
      return activateView(state, action.viewId);
    case "stack/split":
      return splitStack(state, action);
    case "layout/resize":
      return resizeLayout(state, action.splitId, action.ratio);
    case "view/float":
      return floatView(state, action);
    case "view/dock":
      return dockView(state, action.viewId);
    case "view/move":
      return moveView(state, action);
    case "floating/move":
      return moveFloating(state, action.surfaceId, action.x, action.y);
    case "floating/resize":
      return resizeFloating(
        state,
        action.surfaceId,
        action.width,
        action.height,
      );
    case "floating/focus":
      return focusFloating(state, action.surfaceId);
    case "floating/close":
      return closeFloating(state, action.surfaceId);
    case "view/popout":
      return popoutView(state, action);
    case "popout/close":
      return closePopout(state, action.surfaceId);
    default:
      return state;
  }
}

// ---------------------------------------------------------------------------
// View actions
// ---------------------------------------------------------------------------

function openView(
  state: WorkspaceState,
  action: Extract<WorkspaceAction, { type: "view/open" }>,
): WorkspaceState {
  const stackId =
    action.stackId ?? state.activeStackId ?? findFirstStackId(state.tiled);
  const stack = stackId ? state.stacks[stackId] : undefined;
  if (!stack) return state;

  const view = createView(action.viewType, action.title, action);
  return {
    ...state,
    activeStackId: stack.id,
    views: { ...state.views, [view.id]: view },
    stacks: { ...state.stacks, [stack.id]: addView(stack, view.id) },
  };
}

function closeView(state: WorkspaceState, viewId: string): WorkspaceState {
  const view = state.views[viewId];
  if (!view || view.closable === false) return state;

  // The view may live in a floating window instead of the tiled tree.
  const surface = findSurfaceForView(state, viewId);
  if (surface) {
    const stack = state.stacks[surface.stackId];
    if (!stack) return state;
    const closed = removeView(stack, viewId);
    if (closed.viewIds.length > 0) {
      return {
        ...state,
        views: withoutKey(state.views, viewId),
        stacks: { ...state.stacks, [stack.id]: closed },
      };
    }
    // Last tab of the window closed — the window goes with it.
    return closeFloating(state, surface.id);
  }

  // The view may live in a popout window instead of the tiled tree.
  const popout = findPopoutForView(state, viewId);
  if (popout) {
    const stack = state.stacks[popout.stackId];
    if (!stack) return state;
    const closed = removeView(stack, viewId);
    if (closed.viewIds.length > 0) {
      return {
        ...state,
        views: withoutKey(state.views, viewId),
        stacks: { ...state.stacks, [stack.id]: closed },
      };
    }
    // Last tab of the popout closed — the window goes with it.
    return closePopout(state, popout.id);
  }

  const stackId = findStackIdForView(state, viewId);
  const stack = stackId ? state.stacks[stackId] : undefined;
  if (!stack) return state;

  const closed = removeView(stack, viewId);
  let stacks = { ...state.stacks, [stack.id]: closed };
  let tiled = state.tiled;

  // Prune the stack from the tree if it became empty, collapsing its parent
  // split so the sibling takes the full space. The lone tiled stack stays
  // (empty) so the tiled surface never vanishes — but the view still closes.
  if (closed.viewIds.length === 0) {
    const wasRootStack = tiled.type === "stack" && tiled.stackId === stack.id;
    if (!wasRootStack) {
      const pruned = pruneStack(tiled, stack.id);
      if (!pruned) return state;
      tiled = pruned.node;
      stacks = withoutKey(stacks, stack.id);
    }
  }

  return {
    ...state,
    views: withoutKey(state.views, viewId),
    stacks,
    tiled,
    // Closing the active stack's view leaves focus unassigned until the
    // user clicks another tab strip.
    activeStackId:
      state.activeStackId === stack.id ? null : state.activeStackId,
  };
}

function activateView(state: WorkspaceState, viewId: string): WorkspaceState {
  const stackId = findStackIdForView(state, viewId);
  const stack = stackId ? state.stacks[stackId] : undefined;
  if (!stack || !holdsView(stack, viewId)) return state;

  return {
    ...state,
    activeStackId: stack.id,
    stacks: { ...state.stacks, [stack.id]: activateTab(stack, viewId) },
  };
}

function moveView(
  state: WorkspaceState,
  action: Extract<WorkspaceAction, { type: "view/move" }>,
): WorkspaceState {
  const { viewId, targetStackId, edge } = action;
  if (!canMoveView(state, viewId, targetStackId)) return state;

  const sourcePopout = findPopoutForView(state, viewId);
  const sourceSurface = sourcePopout
    ? undefined
    : findSurfaceForView(state, viewId);
  const sourceStackId =
    sourcePopout?.stackId ??
    sourceSurface?.stackId ??
    findStackIdForView(state, viewId);
  if (!sourceStackId) return state;

  // Edge splits are a tiled-tree operation; floating and popout targets
  // take center.
  const effectiveEdge: DropEdge = isSurfaceStack(state, targetStackId)
    ? "center"
    : edge;

  if (sourceStackId === targetStackId) {
    if (effectiveEdge === "center") return activateView(state, viewId);
    // Splitting a stack against itself needs another tab to leave behind.
    if (state.stacks[sourceStackId].viewIds.length <= 1) return state;
  }

  // 1) Detach the view from its current stack.
  const sourceStack = state.stacks[sourceStackId];
  let stacks = state.stacks;
  let tiled = state.tiled;
  let floating = state.floating;
  let popouts = state.popouts;

  if (sourcePopout) {
    const detached = removeView(sourceStack, viewId);
    if (detached.viewIds.length > 0) {
      stacks = { ...stacks, [sourceStackId]: detached };
    } else {
      // An empty popout window disappears with its last view.
      stacks = withoutKey(stacks, sourceStackId);
      popouts = withoutKey(popouts, sourcePopout.id);
    }
  } else if (sourceSurface) {
    const detached = removeView(sourceStack, viewId);
    if (detached.viewIds.length > 0) {
      stacks = { ...stacks, [sourceStackId]: detached };
    } else {
      // An empty floating window disappears with its last view.
      stacks = withoutKey(stacks, sourceStackId);
      floating = withoutKey(floating, sourceSurface.id);
    }
  } else {
    const detachedFrom = detachFromTiledStack(state, sourceStack, viewId);
    if (!detachedFrom) return state;
    stacks = detachedFrom.stacks;
    tiled = detachedFrom.tiled;
  }

  // 2) Insert into the target.
  if (effectiveEdge === "center") {
    return {
      ...state,
      stacks: {
        ...stacks,
        [targetStackId]: addView(state.stacks[targetStackId], viewId),
      },
      tiled,
      floating,
      popouts,
      activeStackId: targetStackId,
    };
  }

  // Edge drop: a fresh stack beside the target in the tiled tree, 50/50.
  const newStack = createStack([viewId]);
  const direction =
    edge === "left" || edge === "right" ? "horizontal" : "vertical";
  const before = edge === "left" || edge === "top";
  const splitRoot = splitAtEdge(
    tiled,
    targetStackId,
    newStack.id,
    direction,
    before,
  );
  if (splitRoot === tiled) return state; // target stack not in the tree

  return {
    ...state,
    stacks: { ...stacks, [newStack.id]: newStack },
    tiled: splitRoot,
    floating,
    popouts,
    activeStackId: newStack.id,
  };
}

// ---------------------------------------------------------------------------
// Splitting
// ---------------------------------------------------------------------------

function splitStack(
  state: WorkspaceState,
  action: Extract<WorkspaceAction, { type: "stack/split" }>,
): WorkspaceState {
  const stackId = action.stackId ?? state.activeStackId;
  if (!stackId) return state;
  const stack = state.stacks[stackId];
  if (!stack) return state;

  // Splitting is a tiled-tree operation. Floating windows and popouts host
  // a single unsplittable stack, so "split" there degrades to opening a
  // tab (or moving a view into the window as a tab).
  if (isSurfaceStack(state, stackId)) {
    if (action.viewType) {
      const view = createView(action.viewType, action.title, action);
      return {
        ...state,
        views: { ...state.views, [view.id]: view },
        stacks: { ...state.stacks, [stack.id]: addView(stack, view.id) },
        activeStackId: stack.id,
      };
    }
    if (action.viewId) {
      return moveView(state, {
        type: "view/move",
        viewId: action.viewId,
        targetStackId: stackId,
        edge: "center",
      });
    }
    return state;
  }

  let views = state.views;
  let seedViewId: string | null = null;

  if (action.viewType) {
    const view = createView(action.viewType, action.title, action);
    views = { ...views, [view.id]: view };
    seedViewId = view.id;
  } else if (action.viewId) {
    const view = state.views[action.viewId];
    if (!view) return state;
    if (!holdsView(stack, action.viewId)) return state;

    const source = removeView(stack, action.viewId);
    // The view is the stack's only content: a split would just relocate it
    // (and orphan an empty stack) — leave the stack as it is.
    if (source.viewIds.length === 0) return state;

    const newStack = createStack([action.viewId]);
    return {
      ...state,
      views,
      stacks: {
        ...state.stacks,
        [stack.id]: source,
        [newStack.id]: newStack,
      },
      tiled: splitBeside(
        state.tiled,
        stack.id,
        newStack.id,
        action.direction,
        action.ratio,
      ),
      activeStackId: newStack.id,
    };
  }
  // Neither viewType nor viewId: an empty new stack.

  const newStack = createStack(seedViewId ? [seedViewId] : []);
  return {
    ...state,
    views,
    stacks: { ...state.stacks, [newStack.id]: newStack },
    tiled: splitBeside(
      state.tiled,
      stack.id,
      newStack.id,
      action.direction,
      action.ratio,
    ),
    activeStackId: newStack.id,
  };
}

function resizeLayout(
  state: WorkspaceState,
  splitId: string,
  ratio: number,
): WorkspaceState {
  const tiled = resizeSplit(state.tiled, splitId, ratio);
  return tiled === state.tiled ? state : { ...state, tiled };
}

// ---------------------------------------------------------------------------
// Floating surfaces
// ---------------------------------------------------------------------------

function floatView(
  state: WorkspaceState,
  action: Extract<WorkspaceAction, { type: "view/float" }>,
): WorkspaceState {
  let viewId: string;
  let views = state.views;
  let stacks = state.stacks;
  let tiled = state.tiled;

  if (action.viewId) {
    const view = state.views[action.viewId];
    if (!view || view.pinned) return state;
    if (findSurfaceForView(state, action.viewId)) return state; // already floating
    if (findPopoutForView(state, action.viewId)) return state; // already popped out

    const sourceId = findStackIdForView(state, action.viewId);
    const source = sourceId ? state.stacks[sourceId] : undefined;
    if (!source) return state;

    const detachedFrom = detachFromTiledStack(state, source, action.viewId);
    if (!detachedFrom) return state;
    stacks = detachedFrom.stacks;
    tiled = detachedFrom.tiled;
    viewId = action.viewId;
  } else if (action.viewType) {
    const view = createView(action.viewType, action.title, action);
    views = { ...views, [view.id]: view };
    viewId = view.id;
  } else {
    return state;
  }

  const newStack = createStack([viewId]);
  // Default geometry cascades so successive floats don't perfectly overlap.
  const geometry =
    action.geometry ?? cascadeGeometry(Object.keys(state.floating).length);
  const surface: FloatingSurface = {
    id: createId("float"),
    stackId: newStack.id,
    ...geometry,
    zIndex: state.nextZIndex,
  };

  return {
    views,
    stacks: { ...stacks, [newStack.id]: newStack },
    tiled,
    activeStackId: newStack.id,
    floating: { ...state.floating, [surface.id]: surface },
    popouts: state.popouts,
    nextZIndex: state.nextZIndex + 1,
  };
}

function dockView(state: WorkspaceState, viewId: string): WorkspaceState {
  if (state.views[viewId]?.pinned) return state;
  const float = findSurfaceForView(state, viewId);
  const popout = findPopoutForView(state, viewId);
  const surface = float ?? popout;
  if (!surface) return state;
  const sourceStack = state.stacks[surface.stackId];
  if (!sourceStack) return state;
  const detached = removeView(sourceStack, viewId);

  // Dock target: the focused stack if it is tiled, else the first tiled one.
  const activeIsTiled =
    state.activeStackId !== null && !isSurfaceStack(state, state.activeStackId);
  const targetId =
    (activeIsTiled ? state.activeStackId : undefined) ??
    findFirstStackId(state.tiled);
  if (!targetId) return state;
  const target = state.stacks[targetId];
  if (!target) return state;

  let stacks = { ...state.stacks, [target.id]: addView(target, viewId) };
  let floating = state.floating;
  let popouts = state.popouts;
  if (detached.viewIds.length > 0) {
    stacks = { ...stacks, [sourceStack.id]: detached };
  } else if (float) {
    // The floating window was hosting only this view — it goes away.
    stacks = withoutKey(stacks, sourceStack.id);
    floating = withoutKey(floating, float.id);
  } else if (popout) {
    // The popout window was hosting only this view — it goes away.
    stacks = withoutKey(stacks, sourceStack.id);
    popouts = withoutKey(popouts, popout.id);
  } else {
    return state;
  }

  return {
    ...state,
    stacks,
    floating,
    popouts,
    activeStackId: target.id,
  };
}

/**
 * Move a view into a popout browser window: a dedicated single-view stack
 * hosted by a PopoutSurface. The live Window handle is managed by the
 * popouts hook layer; state keeps only serializable facts.
 */
function popoutView(
  state: WorkspaceState,
  action: Extract<WorkspaceAction, { type: "view/popout" }>,
): WorkspaceState {
  const view = state.views[action.viewId];
  if (!view || view.pinned) return state;
  if (
    findSurfaceForView(state, action.viewId) ||
    findPopoutForView(state, action.viewId)
  ) {
    return state; // already on a non-tiled surface
  }

  const sourceId = findStackIdForView(state, action.viewId);
  const source = sourceId ? state.stacks[sourceId] : undefined;
  if (!source) return state;

  let stacks = state.stacks;
  let tiled = state.tiled;
  let floating = state.floating;

  const sourceFloat = findSurfaceForStack(state, source.id);
  const detached = removeView(source, action.viewId);
  if (detached.viewIds.length > 0) {
    stacks = { ...stacks, [source.id]: detached };
  } else if (sourceFloat) {
    // The floating window was hosting only this view — it goes away.
    stacks = withoutKey(stacks, source.id);
    floating = withoutKey(floating, sourceFloat.id);
  } else {
    const detachedFrom = detachFromTiledStack(state, source, action.viewId);
    if (!detachedFrom) return state;
    stacks = detachedFrom.stacks;
    tiled = detachedFrom.tiled;
  }

  const newStack = createStack([action.viewId]);
  const surface: PopoutSurface = {
    id: action.surfaceId,
    stackId: newStack.id,
    width: action.width ?? DEFAULT_POPOUT_WIDTH,
    height: action.height ?? DEFAULT_POPOUT_HEIGHT,
  };

  return {
    views: state.views,
    stacks: { ...stacks, [newStack.id]: newStack },
    tiled,
    activeStackId: newStack.id,
    floating,
    popouts: { ...state.popouts, [surface.id]: surface },
    nextZIndex: state.nextZIndex,
  };
}

/** Close a popout window and every view inside it. */
function closePopout(state: WorkspaceState, surfaceId: string): WorkspaceState {
  const surface = state.popouts[surfaceId];
  if (!surface) return state;
  const stack = state.stacks[surface.stackId];

  let views = state.views;
  if (stack) {
    for (const viewId of stack.viewIds) {
      views = withoutKey(views, viewId);
    }
  }

  return {
    ...state,
    views,
    stacks: stack ? withoutKey(state.stacks, stack.id) : state.stacks,
    popouts: withoutKey(state.popouts, surfaceId),
    activeStackId:
      state.activeStackId === surface.stackId ? null : state.activeStackId,
  };
}

function moveFloating(
  state: WorkspaceState,
  surfaceId: string,
  x: number,
  y: number,
): WorkspaceState {
  const surface = state.floating[surfaceId];
  if (!surface) return state;
  if (surface.x === x && surface.y === y) return state;
  return {
    ...state,
    floating: { ...state.floating, [surfaceId]: { ...surface, x, y } },
  };
}

function resizeFloating(
  state: WorkspaceState,
  surfaceId: string,
  width: number,
  height: number,
): WorkspaceState {
  const surface = state.floating[surfaceId];
  if (!surface) return state;
  const clamped = clampSurfaceSize(width, height);
  if (clamped.width === surface.width && clamped.height === surface.height) {
    return state;
  }
  return {
    ...state,
    floating: { ...state.floating, [surfaceId]: { ...surface, ...clamped } },
  };
}

function focusFloating(
  state: WorkspaceState,
  surfaceId: string,
): WorkspaceState {
  const surface = state.floating[surfaceId];
  if (!surface) return state;

  // Already in front: just make sure its stack holds focus.
  if (surface.zIndex === state.nextZIndex - 1) {
    return state.activeStackId === surface.stackId
      ? state
      : { ...state, activeStackId: surface.stackId };
  }
  return {
    ...state,
    activeStackId: surface.stackId,
    floating: {
      ...state.floating,
      [surfaceId]: { ...surface, zIndex: state.nextZIndex },
    },
    nextZIndex: state.nextZIndex + 1,
  };
}

function closeFloating(
  state: WorkspaceState,
  surfaceId: string,
): WorkspaceState {
  const surface = state.floating[surfaceId];
  if (!surface) return state;
  const stack = state.stacks[surface.stackId];
  if (stack?.viewIds.some((id) => state.views[id]?.closable === false)) return state;

  let views = state.views;
  if (stack) {
    for (const viewId of stack.viewIds) {
      views = withoutKey(views, viewId);
    }
  }

  return {
    ...state,
    views,
    stacks: stack ? withoutKey(state.stacks, stack.id) : state.stacks,
    floating: withoutKey(state.floating, surfaceId),
    activeStackId:
      state.activeStackId === surface.stackId ? null : state.activeStackId,
  };
}

// ---------------------------------------------------------------------------
// Keymap commands
// ---------------------------------------------------------------------------

/**
 * Resolve a high-level keymap command against current state. Commands act on
 * the active view of the active stack (tiled or floating).
 */
export function applyWorkspaceCommand(
  state: WorkspaceState,
  command: WorkspaceCommand,
): WorkspaceState {
  switch (command) {
    case "view/close": {
      const viewId = activeViewId(state);
      return viewId ? closeView(state, viewId) : state;
    }
    case "view/activate-next":
      return cycleActiveView(state, 1);
    case "view/activate-prev":
      return cycleActiveView(state, -1);
    case "view/float": {
      const viewId = activeViewId(state);
      return viewId ? floatView(state, { type: "view/float", viewId }) : state;
    }
    case "view/dock": {
      const viewId = activeViewId(state);
      return viewId ? dockView(state, viewId) : state;
    }
    case "view/popout": {
      const viewId = activeViewId(state);
      return viewId
        ? popoutView(state, {
            type: "view/popout",
            surfaceId: createId("popout"),
            viewId,
          })
        : state;
    }
    default:
      return state;
  }
}

function activeViewId(state: WorkspaceState): string | null {
  const stack = state.activeStackId
    ? state.stacks[state.activeStackId]
    : undefined;
  return stack?.activeViewId ?? null;
}

function cycleActiveView(state: WorkspaceState, delta: number): WorkspaceState {
  const stack = state.activeStackId
    ? state.stacks[state.activeStackId]
    : undefined;
  if (!stack) return state;
  const next = cycleActive(stack, delta);
  if (next === stack) return state;
  return { ...state, stacks: { ...state.stacks, [stack.id]: next } };
}

// ---------------------------------------------------------------------------
// Shared detach helper
// ---------------------------------------------------------------------------

/**
 * Remove a view from its tiled stack. Empty non-tiled stacks are pruned from
 * the tree (collapsing their split); the lone empty tiled stack is kept so
 * the tiled surface never vanishes. Returns null if pruning failed
 * (caller keeps state unchanged).
 */
function detachFromTiledStack(
  state: WorkspaceState,
  source: TabStack,
  viewId: string,
): { stacks: WorkspaceState["stacks"]; tiled: LayoutNode } | null {
  const detached = removeView(source, viewId);
  const isRootStack =
    state.tiled.type === "stack" && state.tiled.stackId === source.id;

  if (detached.viewIds.length > 0 || isRootStack) {
    return {
      stacks: { ...state.stacks, [source.id]: detached },
      tiled: state.tiled,
    };
  }

  const pruned = pruneStack(state.tiled, source.id);
  if (!pruned) return null;
  return {
    stacks: withoutKey(state.stacks, source.id),
    tiled: pruned.node,
  };
}

// ---------------------------------------------------------------------------
// Public query helpers — stable API for consumers of the lib
// ---------------------------------------------------------------------------

export function findStack(
  state: WorkspaceState,
  stackId: string,
): TabStack | undefined {
  return state.stacks[stackId];
}

export function findStackForView(
  state: WorkspaceState,
  viewId: string,
): TabStack | undefined {
  const stackId = findStackIdForView(state, viewId);
  return stackId ? state.stacks[stackId] : undefined;
}

export function isLayoutStack(node: LayoutNode): node is LayoutStack {
  return node.type === "stack";
}

export { createView, createStack } from "./model/stack";

/** Pinned views may move between stacks only within the same surface kind. */
export function canMoveView(
  state: WorkspaceState,
  viewId: string,
  targetStackId: string,
): boolean {
  const view = state.views[viewId];
  if (!view || !state.stacks[targetStackId]) return false;
  const sourceStackId = findStackIdForView(state, viewId);
  if (!sourceStackId) return false;
  if (!view.pinned) return true;
  const kind = (stackId: string) =>
    findSurfaceForStack(state, stackId)
      ? "floating"
      : isSurfaceStack(state, stackId) ? "popout" : "tiled";
  return kind(sourceStackId) === kind(targetStackId);
}

/**
 * Tiny record utilities shared by the model layer. Pure, immutable.
 */

/** Copy a record without the given key. */
export function withoutKey<T extends Record<string, unknown>>(
 record: T,
 key: string,
): T {
 const copy = { ...record } as T;
 delete (copy as Record<string, unknown>)[key];
 return copy;
}

/**
 * Stack model — the "stacktab" layer. Pure operations on a single TabStack
 * record and view records: adding, removing, activating tabs. Knows nothing
 * about surfaces or the layout tree; the reducer composes these with the
 * layout and surface models.
 */

import { createId } from "../ids";
import type { TabStack, WorkspaceView } from "../types";

/** Create a view record. */
export function createView(
 type: string,
 title?: string,
 options: Pick<WorkspaceView, "closable" | "pinned"> = {},
): WorkspaceView {
 return { id: createId("view"), type, title: title ?? type,
  ...(options.closable !== undefined ? { closable: options.closable } : {}),
  ...(options.pinned !== undefined ? { pinned: options.pinned } : {}),
 };
}

/** Create a stack record, optionally seeded with views (first is active). */
export function createStack(viewIds: string[] = []): TabStack {
 return {
  id: createId("stack"),
  viewIds: [...viewIds],
  activeViewId: viewIds[0] ?? null,
 };
}

/** Append a view as a tab and activate it. */
export function addView(stack: TabStack, viewId: string): TabStack {
 return {
  ...stack,
  viewIds: [...stack.viewIds, viewId],
  activeViewId: viewId,
 };
}

/**
 * Remove a view's tab. Closing the active tab promotes the first remaining
 * tab; removing the last tab yields an empty stack (the caller decides
 * whether an empty stack is pruned, kept, or destroyed with its surface).
 */
export function removeView(stack: TabStack, viewId: string): TabStack {
 const viewIds = stack.viewIds.filter((id) => id !== viewId);
 const activeViewId =
  stack.activeViewId === viewId ? (viewIds[0] ?? null) : stack.activeViewId;
 return { ...stack, viewIds, activeViewId };
}

/** Activate an existing tab. */
export function activateView(stack: TabStack, viewId: string): TabStack {
 return stack.activeViewId === viewId
  ? stack
  : { ...stack, activeViewId: viewId };
}

/** Move the active tab forward (delta = 1) or backward (delta = -1), wrapping. */
export function cycleActive(stack: TabStack, delta: number): TabStack {
 if (stack.viewIds.length < 2) return stack;
 const index = stack.viewIds.indexOf(stack.activeViewId ?? "");
 const next = (index + delta + stack.viewIds.length) % stack.viewIds.length;
 return { ...stack, activeViewId: stack.viewIds[next] };
}

/** Does this stack hold the view as a tab? */
export function holdsView(
 stack: TabStack | undefined,
 viewId: string,
): boolean {
 return stack?.viewIds.includes(viewId) ?? false;
}

/**
 * Layout model — pure operations on the tiled LayoutNode tree. Knows nothing
 * about view records or floating surfaces: membership questions are answered
 * through an injected `holds` predicate, keeping this module testable in
 * isolation.
 */

import { createId } from "../ids";
import type { LayoutNode } from "../types";

/** Split ratios are clamped so no pane can collapse below 10%. */
export function clampRatio(ratio: number): number {
  return Math.min(0.9, Math.max(0.1, ratio));
}

/**
 * Set a split's ratio. Returns the same node when nothing changed so
 * listeners are not notified.
 */
export function resizeSplit(
  node: LayoutNode,
  splitId: string,
  ratio: number,
): LayoutNode {
  const clamped = clampRatio(ratio);

  function walk(current: LayoutNode): LayoutNode {
    if (current.type === "stack") return current;
    if (current.id === splitId) {
      return current.ratio === clamped
        ? current
        : { ...current, ratio: clamped };
    }
    const first = walk(current.first);
    const second = walk(current.second);
    if (first === current.first && second === current.second) return current;
    return { ...current, first, second };
  }

  return walk(node);
}

/**
 * Split the tree at the target stack: the target becomes the first child of
 * a new split and the fresh stack the second (or, at ratio > 0.5, swap).
 * Returns the same node when the target is absent.
 */
export function splitBeside(
  node: LayoutNode,
  targetStackId: string,
  newStackId: string,
  direction: "horizontal" | "vertical",
  ratio = 0.5,
): LayoutNode {
  if (node.type === "stack") {
    if (node.stackId !== targetStackId) return node;
    return {
      type: "split",
      id: createId("split"),
      direction,
      ratio: clampRatio(ratio),
      first: node,
      second: { type: "stack", stackId: newStackId },
    };
  }
  return {
    ...node,
    first: splitBeside(node.first, targetStackId, newStackId, direction, ratio),
    second: splitBeside(
      node.second,
      targetStackId,
      newStackId,
      direction,
      ratio,
    ),
  };
}

/**
 * Split the tree at the target stack, placing the fresh stack on the given
 * side (before = left/top) as an even 50/50 split — the drag-and-drop edge
 * insertion. Returns the same node when the target is absent.
 */
export function splitAtEdge(
  node: LayoutNode,
  targetStackId: string,
  newStackId: string,
  direction: "horizontal" | "vertical",
  before: boolean,
): LayoutNode {
  if (node.type === "stack") {
    if (node.stackId !== targetStackId) return node;
    const inserted: LayoutNode = { type: "stack", stackId: newStackId };
    return {
      type: "split",
      id: createId("split"),
      direction,
      ratio: 0.5,
      first: before ? inserted : node,
      second: before ? node : inserted,
    };
  }
  const first = splitAtEdge(
    node.first,
    targetStackId,
    newStackId,
    direction,
    before,
  );
  const second = splitAtEdge(
    node.second,
    targetStackId,
    newStackId,
    direction,
    before,
  );
  if (first === node.first && second === node.second) return node;
  return { ...node, first, second };
}

/**
 * Remove an empty stack from the tree, collapsing its parent split so the
 * sibling takes the full space. Returns null if the stack could not be
 * pruned (absent, or it IS the root — the caller decides whether the lone
 * empty root stack is kept so the tiled surface never vanishes).
 */
export function pruneStack(
  node: LayoutNode,
  stackId: string,
): { node: LayoutNode } | null {
  if (node.type === "stack") return null;

  const { first, second } = node;
  if (first.type === "stack" && first.stackId === stackId) {
    return { node: second };
  }
  if (second.type === "stack" && second.stackId === stackId) {
    return { node: first };
  }

  const prunedFirst = pruneStack(first, stackId);
  if (prunedFirst) return { node: { ...node, first: prunedFirst.node } };

  const prunedSecond = pruneStack(second, stackId);
  if (prunedSecond) return { node: { ...node, second: prunedSecond.node } };

  return null;
}

/** First stack in depth-first order — the fallback drop/activation target. */
export function findFirstStackId(node: LayoutNode): string | undefined {
  if (node.type === "stack") return node.stackId;
  return (
    findFirstStackId(node.first) ?? findFirstStackId(node.second) ?? undefined
  );
}

/**
 * Find the tiled stack that satisfies the membership predicate, in depth-first
 * order. Surface-level callers pass a predicate backed by stack records;
 * floating stacks are checked before the tree is walked.
 */
export function findStackIdForView(
  node: LayoutNode,
  holds: (stackId: string) => boolean,
): string | undefined {
  if (node.type === "stack")
    return holds(node.stackId) ? node.stackId : undefined;
  return (
    findStackIdForView(node.first, holds) ??
    findStackIdForView(node.second, holds)
  );
}

/**
 * Surface model — floating-window queries and geometry, plus the space-level
 * view lookup that unifies tiled and floating placement. Pure functions over
 * WorkspaceState.
 *
 * The central invariant this module encodes: a view lives in exactly one
 * stack, and that stack is reachable either through a floating surface or
 * through the tiled tree — never neither, never both.
 */

import { findStackIdForView as findTiledStackIdForView } from "./layout";
import type { FloatingSurface, PopoutSurface, WorkspaceState } from "../types";

/** Minimum floating window dimensions the reducer enforces. */
export const MIN_FLOATING_WIDTH = 200;
export const MIN_FLOATING_HEIGHT = 140;

/** Default popout browser window dimensions. */
export const DEFAULT_POPOUT_WIDTH = 520;
export const DEFAULT_POPOUT_HEIGHT = 400;

/** The surface hosting the stack, if the stack is floating. */
export function findSurfaceForStack(
 state: WorkspaceState,
 stackId: string,
): FloatingSurface | undefined {
 return Object.values(state.floating).find((s) => s.stackId === stackId);
}

/** The popout surface hosting the stack, if the stack is popped out. */
export function findPopoutForStack(
 state: WorkspaceState,
 stackId: string,
): PopoutSurface | undefined {
 return Object.values(state.popouts).find((s) => s.stackId === stackId);
}

/** The floating surface whose stack holds the view, if any. */
export function findSurfaceForView(
 state: WorkspaceState,
 viewId: string,
): FloatingSurface | undefined {
 for (const surface of Object.values(state.floating)) {
  if (state.stacks[surface.stackId]?.viewIds.includes(viewId)) {
   return surface;
  }
 }
 return undefined;
}

/** The popout surface whose stack holds the view, if any. */
export function findPopoutForView(
 state: WorkspaceState,
 viewId: string,
): PopoutSurface | undefined {
 for (const surface of Object.values(state.popouts)) {
  if (state.stacks[surface.stackId]?.viewIds.includes(viewId)) {
   return surface;
  }
 }
 return undefined;
}

/**
 * Is this stack hosted by a non-tiled surface (floating window or popout)?
 * Such stacks host a single unsplittable stack, so edge drops and splits
 * targeting them degrade to "center".
 */
export function isSurfaceStack(
 state: WorkspaceState,
 stackId: string,
): boolean {
 return (
  findSurfaceForStack(state, stackId) !== undefined ||
  findPopoutForStack(state, stackId) !== undefined
 );
}

/**
 * Find the stack that actually CONTAINS a view — checking floating surfaces
 * first, then the tiled tree. Membership-checked: a stack that merely
 * appears first in the tree must never be returned for an unrelated view.
 */
export function findStackIdForView(
 state: WorkspaceState,
 viewId: string,
): string | undefined {
 for (const surface of Object.values(state.floating)) {
  if (state.stacks[surface.stackId]?.viewIds.includes(viewId)) {
   return surface.stackId;
  }
 }
 for (const surface of Object.values(state.popouts)) {
  if (state.stacks[surface.stackId]?.viewIds.includes(viewId)) {
   return surface.stackId;
  }
 }
 return findTiledStackIdForView(
  state.tiled,
  (stackId) => state.stacks[stackId]?.viewIds.includes(viewId) ?? false,
 );
}

/**
 * Default geometry for a newly floated window: cascades by 28px per existing
 * surface so successive floats don't perfectly overlap.
 */
export function cascadeGeometry(existingSurfaceCount: number): {
 x: number;
 y: number;
 width: number;
 height: number;
} {
 const offset = existingSurfaceCount * 28;
 return { x: 48 + offset, y: 48 + offset, width: 360, height: 260 };
}

/** Clamp a floating window's size to the reducer's minimums. */
export function clampSurfaceSize(
 width: number,
 height: number,
): { width: number; height: number } {
 return {
  width: Math.max(MIN_FLOATING_WIDTH, width),
  height: Math.max(MIN_FLOATING_HEIGHT, height),
 };
}

/**
 * Framework-agnostic workspace store. Built on a subscribe/getSnapshot
 * contract so React binds to it with useSyncExternalStore — and so a future
 * popout browser window can subscribe to the exact same store instance.
 */

import type { WorkspaceAction } from "./actions";
import { applyWorkspaceCommand } from "./reducer";
import type { WorkspaceCommand } from "./keymap";
import { reducer } from "./reducer";
import type { WorkspaceState } from "./types";

export interface WorkspaceStore {
  getState(): WorkspaceState;
  dispatch(action: WorkspaceAction): void;
  /** Apply a high-level command (keymap layer); resolves the active view. */
  applyCommand(command: WorkspaceCommand): void;
  /**
   * Replace the entire state (persistence restore). Callers are responsible
   * for passing a valid WorkspaceState — see lib/workspace/persistence.ts.
   */
  hydrate(state: WorkspaceState): void;
  subscribe(listener: () => void): () => void;
}

export function createWorkspaceStore(
  initialState: WorkspaceState,
): WorkspaceStore {
  let state = initialState;
  const listeners = new Set<() => void>();

  return {
    getState: () => state,
    dispatch(action: WorkspaceAction) {
      const next = reducer(state, action);
      if (next === state) return;
      state = next;
      for (const listener of listeners) listener();
    },
    applyCommand(command: WorkspaceCommand) {
      const next = applyWorkspaceCommand(state, command);
      if (next === state) return;
      state = next;
      for (const listener of listeners) listener();
    },
    hydrate(next: WorkspaceState) {
      if (next === state) return;
      state = next;
      for (const listener of listeners) listener();
    },
    subscribe(listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

/**
 * Convenience builders for constructing an initial WorkspaceState without
 * hand-writing ids. All pure; ids are generated for you.
 */

import { createId } from "./ids";
import { createView, createStack } from "./reducer";
import type {
  LayoutNode,
  TabStack,
  WorkspaceState,
  WorkspaceView,
} from "./types";

export interface InitialStackSpec {
  /** View types to open in this stack, in tab order. */
  views: { type: string; title?: string; closable?: boolean; pinned?: boolean }[];
}

export interface InitialSplitSpec {
  direction: "horizontal" | "vertical";
  ratio?: number;
  first: InitialNodeSpec;
  second: InitialNodeSpec;
}

export type InitialNodeSpec = InitialStackSpec | InitialSplitSpec;

export function createInitialState(rootSpec: InitialNodeSpec): WorkspaceState {
  const views: Record<string, WorkspaceView> = {};
  const stacks: Record<string, TabStack> = {};
  let activeStackId: string | null = null;

  function build(spec: InitialNodeSpec): LayoutNode {
    if ("direction" in spec) {
      return {
        type: "split",
        id: createId("split"),
        direction: spec.direction,
        ratio: spec.ratio ?? 0.5,
        first: build(spec.first),
        second: build(spec.second),
      };
    }

    const stack = createStack();
    for (const viewSpec of spec.views) {
      const view = createView(viewSpec.type, viewSpec.title, viewSpec);
      views[view.id] = view;
      stack.viewIds.push(view.id);
    }
    stack.activeViewId = stack.viewIds[0] ?? null;
    stacks[stack.id] = stack;
    if (!activeStackId) activeStackId = stack.id;
    return { type: "stack", stackId: stack.id };
  }

  const tiled = build(rootSpec);
  return {
    views,
    stacks,
    tiled,
    activeStackId,
    floating: {},
    popouts: {},
    nextZIndex: 1,
  };
}

/**
 * Workspace configuration — how the user talks to the workspace. Config is
 * deliberately NOT part of WorkspaceState: it describes behavior/controls,
 * not workspace content, so it travels via context instead of the reducer.
 */

import type { ModifierKey, WorkspaceKeymap } from "./keymap";
import { defaultKeymap } from "./keymap";

export interface WorkspaceFloatingConfig {
  /** "frame" renders a title bar; "frameless" renders only the stack. */
  chrome: "frame" | "frameless";
  /** Modifier held on pointer-down anywhere to move a window (e.g. ctrl-drag). */
  dragModifier: ModifierKey | null;
  /** Optional modifier + drag to resize from the nearest edge. */
  resizeModifier: ModifierKey | null;
}

/** Partial config consumers may provide; missing fields fall back to defaults. */
export interface WorkspaceConfigInput {
  floating?: Partial<WorkspaceFloatingConfig>;
  keymap?: WorkspaceKeymap;
}

export interface WorkspaceConfig {
  floating: WorkspaceFloatingConfig;
  keymap: WorkspaceKeymap;
}

export const defaultWorkspaceConfig: WorkspaceConfig = {
  floating: {
    chrome: "frame",
    dragModifier: "ctrl",
    resizeModifier: null,
  },
  keymap: defaultKeymap,
};

/** Merge a partial consumer config over the defaults (shallow per section). */
export function resolveConfig(partial?: WorkspaceConfigInput): WorkspaceConfig {
  return {
    floating: { ...defaultWorkspaceConfig.floating, ...partial?.floating },
    keymap: { ...defaultWorkspaceConfig.keymap, ...partial?.keymap },
  };
}

/**
 * Workspace keymap — pure data mapping command ids to key combinations.
 *
 * The keymap is CONFIG, not state: it describes how the user talks to the
 * workspace, not what the workspace contains. It travels in
 * WorkspaceConfig and is interpreted by hooks/use-workspace-keymap.ts.
 *
 * Combo syntax: modifier keys joined with "+", actual key last.
 *   "mod+w"        — mod = Ctrl on Linux/Windows, Cmd on macOS
 *   "ctrl+Tab"     — literal modifiers and key names
 *   "alt+ArrowDown" — event.key names, case-insensitive
 *
 * Note: avoid combos the browser reserves (e.g. mod+w / ctrl+t / ctrl+n) —
 * page JavaScript cannot intercept those. The defaults stick to alt+ combos,
 * which are reliably preventable; consumers are expected to override.
 */

export type ModifierKey = "ctrl" | "alt" | "meta" | "shift";

/** e.g. "mod+w", "ctrl+shift+Tab". The key is the last "+-separated part". */
export type KeyCombo = string;

/** High-level workspace operations the keymap can bind. */
export type WorkspaceCommand =
 | "view/close"
 | "view/activate-next"
 | "view/activate-prev"
 | "view/float"
 | "view/dock"
 | "view/popout";

export type WorkspaceKeymap = Partial<
 Record<WorkspaceCommand, KeyCombo | KeyCombo[]>
>;

export const defaultKeymap: Required<WorkspaceKeymap> = {
 "view/close": "alt+w",
 "view/activate-next": "alt+ArrowDown",
 "view/activate-prev": "alt+ArrowUp",
 "view/float": "alt+f",
 "view/dock": "alt+d",
 "view/popout": "alt+p",
};

/**
 * Whether a KeyboardEvent matches a combo. Modifiers must match exactly
 * (except that the browser may fold e.g. AltGraph — handled loosely).
 */
export function eventMatchesCombo(
 combo: KeyCombo,
 event: KeyboardEvent,
): boolean {
 const parts = combo.toLowerCase().split("+");
 const key = parts[parts.length - 1];
 const mods = new Set(parts.slice(0, -1));

 const wantsMod = mods.delete("mod");
 const isMac = /mac/i.test(
  typeof navigator !== "undefined"
   ? navigator.platform || navigator.userAgent
   : "",
 );
 const wantsCtrl = mods.delete("ctrl") || (wantsMod && !isMac);
 const wantsMeta = mods.delete("meta") || (wantsMod && isMac);
 const wantsAlt = mods.delete("alt");
 const wantsShift = mods.delete("shift");
 if (mods.size > 0) return false; // unknown modifier in the combo

 return (
  event.key.toLowerCase() === key &&
  event.ctrlKey === wantsCtrl &&
  event.metaKey === wantsMeta &&
  event.altKey === wantsAlt &&
  event.shiftKey === wantsShift
 );
}

/** Map a DOM modifier name ("ctrl") to its KeyboardEvent property. */
export function modifierToEventKey(
 modifier: ModifierKey,
): "ctrlKey" | "altKey" | "metaKey" | "shiftKey" {
 switch (modifier) {
  case "ctrl":
   return "ctrlKey";
  case "alt":
   return "altKey";
  case "meta":
   return "metaKey";
  case "shift":
   return "shiftKey";
 }
}

/**
 * Drop-edge detection for drag & drop docking, ported from tiling-tabs.
 * Pure geometry: given a pointer position and a stack's bounding rect, find
 * which edge zone the pointer is in. Near an edge (within `threshold` of the
 * stack's normalized extent) means "split at that edge"; anywhere else means
 * "drop as a tab into the stack" (center).
 */

export type DropEdge = "top" | "right" | "bottom" | "left" | "center";

export interface DropPoint {
 x: number;
 y: number;
}

export interface DropRect {
 left: number;
 top: number;
 width: number;
 height: number;
}

export function computeDropEdge(
 point: DropPoint,
 rect: DropRect,
 threshold = 0.24,
): DropEdge {
 if (rect.width <= 0 || rect.height <= 0) return "center";
 const x = Math.min(Math.max((point.x - rect.left) / rect.width, 0), 1);
 const y = Math.min(Math.max((point.y - rect.top) / rect.height, 0), 1);
 const edges: Array<[Exclude<DropEdge, "center">, number]> = [
  ["left", x],
  ["right", 1 - x],
  ["top", y],
  ["bottom", 1 - y],
 ];
 const nearest = edges.reduce((best, edge) =>
  edge[1] < best[1] ? edge : best,
 );
 return nearest[1] <= threshold ? nearest[0] : "center";
}

/**
 * Workspace persistence — serialize/deserialize WorkspaceState.
 *
 * State is plain serializable data, so persistence is a JSON envelope with a
 * schema version plus structural validation on load: corrupted or foreign
 * payloads deserialize to null (callers keep their current state) instead of
 * injecting garbage into the reducer.
 *
 * What is intentionally NOT persisted: view working state (useViewWorkingState
 * is a session-level map) and live Window handles for popouts (the popouts
 * layer re-opens windows for restored surfaces).
 */

import type { LayoutNode, WorkspaceState } from "./types";

const SCHEMA_VERSION = 1;

interface PersistedEnvelope {
  version: number;
  state: WorkspaceState;
}

export function serializeWorkspaceState(state: WorkspaceState): string {
  const envelope: PersistedEnvelope = { version: SCHEMA_VERSION, state };
  return JSON.stringify(envelope);
}

/** Deserialize a payload produced by serializeWorkspaceState. */
export function deserializeWorkspaceState(json: string): WorkspaceState | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(json);
  } catch {
    return null;
  }
  if (typeof parsed !== "object" || parsed === null) return null;
  const envelope = parsed as Partial<PersistedEnvelope>;
  if (envelope.version !== SCHEMA_VERSION) return null;
  if (!isWorkspaceStateShape(envelope.state)) return null;
  return envelope.state;
}

/** Pragmatic structural check — shape only, no referential validation. */
function isWorkspaceStateShape(value: unknown): value is WorkspaceState {
  if (typeof value !== "object" || value === null) return false;
  const state = value as Record<string, unknown>;
  return (
    isRecordOfObjects(state.views) &&
    isRecordOfObjects(state.stacks) &&
    isLayoutNodeShape(state.tiled) &&
    (state.activeStackId === null || typeof state.activeStackId === "string") &&
    isRecordOfObjects(state.floating) &&
    isRecordOfObjects(state.popouts) &&
    typeof state.nextZIndex === "number"
  );
}

function isRecordOfObjects(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null) return false;
  return Object.values(value).every(
    (entry) => typeof entry === "object" && entry !== null,
  );
}

function isLayoutNodeShape(value: unknown): value is LayoutNode {
  if (typeof value !== "object" || value === null) return false;
  const node = value as Record<string, unknown>;
  if (node.type === "stack") return typeof node.stackId === "string";
  if (node.type === "split") {
    return (
      typeof node.id === "string" &&
      (node.direction === "horizontal" || node.direction === "vertical") &&
      typeof node.ratio === "number" &&
      isLayoutNodeShape(node.first) &&
      isLayoutNodeShape(node.second)
    );
  }
  return false;
}
